const fs = require('fs');

function higherDividend(x, divider) {
    return Math.floor(x / divider) * divider;
}

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const cnt1 = parseInt(input[0], 10);
const cnt2 = parseInt(input[1], 10);
const x = parseInt(input[2], 10);
const y = parseInt(input[3], 10);

let count = 0;
let barrier = cnt1 + cnt2;

while (count !== cnt1 + cnt2) {
    const xy = x * y;
    const bad = higherDividend(barrier, xy) / xy;
    const xCountCommon = higherDividend(barrier, y) / y - bad;
    const yCountCommon = higherDividend(barrier, x) / x - bad;
    const xCount = Math.min(xCountCommon, cnt1);
    const yCount = Math.min(yCountCommon, cnt2);
    let currentBad = bad;
    if (xCount < xCountCommon) currentBad += xCountCommon - xCount;
    if (yCount < yCountCommon) currentBad += yCountCommon - yCount;
    const good = barrier - currentBad - xCount - yCount;
    count = good + xCount + yCount;
    barrier += cnt1 + cnt2 - count;
}

console.log(barrier);

